INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('514f473e-a51b-4076-b0de-75285f981850', 'b2b2b2b2-3030-4000-8000-000000000002', 28, 'Dia 28 — Paz', 'Semana 4: Integrar', '{"pch": "A minha paz vos dou\u2026 n\u00e3o como o mundo a d\u00e1. Paz n\u00e3o \u00e9 aus\u00eancia de conflito \u2014 \u00e9 presen\u00e7a de Deus.", "verse": "Jo 14,27", "lectio": "Leia Jo 14,25-31. O Consolador vem.", "practice": "Identifique o ladr\u00e3o de paz. Entregue-o em ora\u00e7\u00e3o.", "question": "O que te rouba a paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;